reference_solutions.python:
import heapq

def networkDelayTime(times, n, k):
    adj = [[] for _ in range(n + 1)]
    for u, v, w in times:
        adj[u].append((v, w))
    dist = [float('inf')] * (n + 1)
    dist[k] = 0
    heap = [(0, k)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            if d + w < dist[v]:
                dist[v] = d + w
                heapq.heappush(heap, (dist[v], v))
    slowest = max(dist[1:])
    return -1 if slowest == float('inf') else slowest

reference_solutions.javascript:
function networkDelayTime(times, n, k) {
  // Bellman-Ford: relax every link until nothing improves.
  const INF = Number.MAX_SAFE_INTEGER;
  const dist = new Array(n + 1).fill(INF);
  dist[k] = 0;
  for (let round = 1; round < n; round++) {
    let changed = false;
    for (const [u, v, w] of times) {
      if (dist[u] !== INF && dist[u] + w < dist[v]) { dist[v] = dist[u] + w; changed = true; }
    }
    if (!changed) break;
  }
  let slowest = 0;
  for (let i = 1; i <= n; i++) slowest = Math.max(slowest, dist[i]);
  return slowest === INF ? -1 : slowest;
}

